#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    long shift = strtol(argv[1], NULL, 10);
    shift %= 26;
    if (shift < 0) shift += 26;
    const char *text = argv[2];
    size_t len = strlen(text);
    if (len > 1024) {
        puts("USAGE");
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)text[i];
        if (c >= 'A' && c <= 'Z') {
            c = (c - 'A' + shift) % 26 + 'A';
        } else if (c >= 'a' && c <= 'z') {
            c = (c - 'a' + shift) % 26 + 'a';
        }
        putc(c, stdout);
    }
    putc('\n', stdout);
    return 0;
}
